-- Nexa Chat şema denetimi: yalnızca SELECT; veri veya şema değiştirmez.
-- Şifreler, mesaj içerikleri ve kişisel veri okunmaz. Sonuç şema metaverisidir.
-- İsimlerin varlığı güvenlik politikalarının doğru çalıştığını kanıtlamaz.
with expected_tables(name) as (values ('admin_audit_logs'), ('blocked_users'), ('call_sessions'), ('call_signals'), ('conversation_locks'), ('conversation_members'), ('conversations'), ('live_drafts'), ('message_reactions'), ('message_requests'), ('messages'), ('notifications'), ('profiles'), ('push_subscriptions'), ('reports'), ('typing_indicators'), ('user_settings')),
expected_functions(name) as (values ('accept_call'), ('accept_message_request'), ('active_admin_count'), ('admin_approve_user'), ('admin_ban_user'), ('admin_deactivate_user'), ('admin_list_pending_users'), ('admin_list_reports'), ('admin_list_users'), ('admin_reactivate_user'), ('admin_reject_user'), ('admin_review_report'), ('admin_set_role'), ('admin_soft_delete_message'), ('admin_unban_user'), ('can_access_chat_media'), ('cancel_call'), ('cancel_message_request'), ('chat_lock_ok'), ('cleanup_expired_live_drafts'), ('cleanup_expired_messages'), ('clear_live_draft'), ('end_call'), ('expire_stale_calls'), ('find_direct_conversation'), ('force_remove_conversation_lock'), ('get_conversation_lock_status'), ('get_live_typing_status'), ('get_locked_conversation_ids'), ('get_message_request_count'), ('get_or_create_direct_conversation'), ('get_unread_counts'), ('get_unread_total_for'), ('handle_new_user'), ('is_admin'), ('is_approved_user'), ('is_blocked_pair'), ('is_call_participant'), ('is_conversation_member'), ('is_live_draft_eligible'), ('is_moderator'), ('list_incoming_message_requests'), ('list_outgoing_message_requests'), ('lock_conversation_now'), ('log_admin_action'), ('mark_conversation_read'), ('mark_missed_call'), ('message_conversation_id'), ('normalize_profile'), ('notify_admins_new_application'), ('on_message_insert'), ('protect_profile_privileged'), ('reject_call'), ('reject_message_request'), ('remove_conversation_pin'), ('search_approved_users'), ('send_message_request'), ('set_conversation_archived'), ('set_conversation_muted'), ('set_conversation_pin'), ('set_disappearing_messages'), ('set_live_typing_enabled'), ('set_message_expiry'), ('set_updated_at'), ('start_call'), ('upsert_live_draft'), ('verify_conversation_pin')),
expected_realtime(name) as (values ('messages'),('conversations'),('conversation_members'),('message_reactions'),('typing_indicators'),('profiles'),('message_requests'),('call_sessions'),('call_signals'),('notifications'),('live_drafts')),
expected_columns(table_name, column_name) as (values ('messages','expires_at'),('conversations','disappearing_seconds'),('conversation_members','live_typing_enabled'),('profiles','approval_status'),('profiles','deactivated_at'))
select jsonb_build_object(
 'missing_tables', (select coalesce(jsonb_agg(e.name order by e.name),'[]'::jsonb) from expected_tables e where to_regclass('public.'||e.name) is null),
 'tables', (select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) order by c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p')),
 'missing_columns', (select coalesce(jsonb_agg(e.table_name||'.'||e.column_name order by e.table_name,e.column_name),'[]'::jsonb) from expected_columns e where not exists (select 1 from information_schema.columns c where c.table_schema='public' and c.table_name=e.table_name and c.column_name=e.column_name)),
 'columns', (select coalesce(jsonb_agg(jsonb_build_object('table',table_name,'name',column_name,'type',data_type,'nullable',is_nullable) order by table_name,ordinal_position),'[]'::jsonb) from information_schema.columns where table_schema='public'),
 'policies', (select coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'command',cmd,'roles',roles,'using',qual,'check',with_check) order by schemaname,tablename,policyname),'[]'::jsonb) from pg_policies where schemaname in ('public','storage','realtime')),
 'missing_functions', (select coalesce(jsonb_agg(e.name order by e.name),'[]'::jsonb) from expected_functions e where not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=e.name)),
 'functions', (select coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'settings',p.proconfig,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE')) order by p.proname,pg_get_function_identity_arguments(p.oid)),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
 'triggers', (select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid)) order by n.nspname,c.relname,t.tgname),'[]'::jsonb) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','auth')),
 'buckets', (select coalesce(jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) order by id),'[]'::jsonb) from storage.buckets),
 'missing_realtime_tables', (select coalesce(jsonb_agg(e.name order by e.name),'[]'::jsonb) from expected_realtime e where not exists (select 1 from pg_publication_tables p where p.pubname='supabase_realtime' and p.schemaname='public' and p.tablename=e.name)),
 'realtime_tables', (select coalesce(jsonb_agg(schemaname||'.'||tablename order by schemaname,tablename),'[]'::jsonb) from pg_publication_tables where pubname='supabase_realtime'),
 'table_privileges', (select coalesce(jsonb_agg(jsonb_build_object('table',table_name,'role',grantee,'privilege',privilege_type) order by table_name,grantee,privilege_type),'[]'::jsonb) from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated'))
) as audit;
